      "proposed_laureates": [
        "Shinji Yuasa",
        "Stuart S. P. Parkin",
        "William H. Butler"
      ],
      "assessment": {
        "nobel_worthiness": "Crystalline MgO tunnel junctions produced giant tunneling magnetoresistance, a striking materials result with lasting importance for spintronics and magnetic storage.",
        "attribution": "Butler's theory identified the symmetry-filtering mechanism, while Yuasa and Parkin independently demonstrated the large effect experimentally.",
        "maturity": "The effect is robust, well understood, and connected to mature device technology.",
        "uncertainties": [
          "The independent experimental discoveries make the precise division of credit and scope of the recognized contribution important."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made strongly correlated electron systems quantitatively tractable and reshaped theoretical condensed matter physics.",
        "attribution": "Georges, Vollhardt, and Kotliar were central to developing and establishing the method; the wider community contributed substantially to its extensions and applications.",
        "maturity": "The framework has decades of successful use and extensive comparison with experiments and numerical methods.",
        "uncertainties": [
          "The award case concerns a theoretical framework rather than a single experimentally isolated discovery, and credit extends beyond these three contributors."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Andrea J. Liu",
        "Corey S. O'Hern",
        "Sidney R. Nagel"
      ],
      "assessment": {
        "nobel_worthiness": "The jamming framework gave disordered materials a powerful account of rigidity and collective behavior near a transition, with broad reach across soft matter and granular physics.",
        "attribution": "These researchers were key in formulating and developing the modern jamming picture, though its foundations were built by a broader community.",
        "maturity": "The phenomenology has been tested in experiments, simulations, and theory over many years.",
        "uncertainties": [
          "The transition's universality and the boundaries of the shared discovery remain debated."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller",
        "Tilman Esslinger"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices enabled controlled quantum simulation of Hubbard physics, creating a new experimental route to strongly interacting many-body systems.",
        "attribution": "These researchers made major contributions to the theoretical framework and landmark experiments that established the platform.",
        "maturity": "The platform is highly controlled and extensively reproduced; its full value for resolving difficult condensed matter problems continues to develop.",
        "uncertainties": [
          "The broad credited group spans distinct contributions, and the most prize-worthy specific result should be defined."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Ramamoorthy Ramesh",
        "Sang-Wook Cheong",
        "Yoshinori Tokura"
      ],
      "assessment": {
        "nobel_worthiness": "Magnetically driven ferroelectricity and strong magnetoelectric coupling revealed an important route to coupling spin and electric polarization in solids.",
        "attribution": "Cheong and Tokura were central to discovering and explaining key multiferroic mechanisms; Ramesh made influential contributions to the field and its materials.",
        "maturity": "The phenomena are established in multiple materials, with substantial experimental and theoretical follow-up.",
        "uncertainties": [
          "The discovery and credit are distributed across several materials and mechanisms, making the award's precise focus consequential."
        ]
      }
    },
